  /**
   * Method under test:
   * {@link ConfigProtos.ProtoOutputControlState#parseFrom(InputStream, ExtensionRegistryLite)}
   */
  @Test
  void testProtoOutputControlStateParseFrom10() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt())).thenThrow(new IOException("foo"));

    // Act and Assert
    assertThrows(IOException.class,
        () -> ConfigProtos.ProtoOutputControlState.parseFrom(input, ExtensionRegistryLite.getEmptyRegistry()));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

  /**
   * Method under test:
   * {@link ConfigProtos.ProtoOutputControlState#parseFrom(InputStream, ExtensionRegistryLite)}
   */
  @Test
  void testProtoOutputControlStateParseFrom11() throws IOException {
    // Arrange
    DataInputStream input = mock(DataInputStream.class);
    when(input.read(Mockito.<byte[]>any(), anyInt(), anyInt()))
        .thenThrow(new InvalidProtocolBufferException("The characteristics of someone or something"));

    // Act and Assert
    assertThrows(InvalidProtocolBufferException.class,
        () -> ConfigProtos.ProtoOutputControlState.parseFrom(input, ExtensionRegistryLite.getEmptyRegistry()));
    verify(input).read(isA(byte[].class), eq(0), eq(4096));
  }

